import sharp from 'sharp';

/**
 * Imágenes reales y mínimas (8×8) para los e2e de subida: el back las decodifica
 * y las vuelve a codificar sin metadata, así que ya no sirven los bytes de
 * relleno con la firma correcta.
 */
export const PNG_REAL = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAACXBIWXMAAAPoAAAD6AG1e1JrAAAAEUlEQVQImWM4ISeHFTEMLQkAkL9BAaxyLUcAAAAASUVORK5CYII=',
  'base64',
);
export const JPG_REAL = Buffer.from(
  '',
  'base64',
);
/** JPEG con EXIF: marca de cámara, programa y coordenadas GPS. */
export const JPG_CON_GPS = Buffer.from(
  '',
  'base64',
);

/** Texto que sólo está en un archivo si conservó el EXIF de `JPG_CON_GPS`. */
export const MARCA_DE_EXIF = Buffer.from('CamaraDePrueba');

/** ¿Conserva metadata EXIF/GPS? */
export async function tieneExif(imagen: Buffer): Promise<boolean> {
  const meta = await sharp(imagen).metadata();
  return meta.exif !== undefined || imagen.includes(MARCA_DE_EXIF);
}
